/* CRC-16/CCITT-FALSE (poly 0x1021, init 0xFFFF). */
static inline uint16_t vl_crc16(const uint8_t *data, size_t len)
{
	uint16_t crc = 0xFFFFu;
	for (size_t i = 0u; i < len; i++) {
		crc = (uint16_t)(crc ^ (uint16_t)((uint16_t)data[i] << 8u));
		for (uint8_t b = 0u; b < 8u; b++) {
			if ((crc & 0x8000u) != 0u) {
				crc = (uint16_t)((uint16_t)(crc << 1u) ^ 0x1021u);
			} else {
				crc = (uint16_t)(crc << 1u);
			}
		}
	}
	return crc;
}

/* COBS encode in -> out (no delimiter). Returns bytes written, 0 if out is too small. */
static inline size_t vl_cobs_encode(const uint8_t *in, size_t len, uint8_t *out, size_t cap)
{
	if (cap == 0u) {
		return 0u;
	}
	size_t code_idx = 0u;
	size_t o = 1u;
	uint8_t code = 1u;
	for (size_t i = 0u; i < len; i++) {
		if (in[i] == 0u) {
			out[code_idx] = code;
			code_idx = o;
			o++;
			code = 1u;
		} else {
			if (o >= cap) {
				return 0u;
			}
			out[o] = in[i];
			o++;
			code++;
			if (code == 0xFFu) {
				out[code_idx] = code;
				code_idx = o;
				o++;
				code = 1u;
			}
		}
		if (o > cap) {
			return 0u;
		}
	}
	if (code_idx >= cap) {
		return 0u;
	}
	out[code_idx] = code;
	return o;
}

/* COBS decode in -> out. Returns bytes written, 0 on malformed input or overflow. */
static inline size_t vl_cobs_decode(const uint8_t *in, size_t len, uint8_t *out, size_t cap)
{
	size_t i = 0u;
	size_t o = 0u;
	while (i < len) {
		const uint8_t code = in[i];
		if (code == 0u) {
			return 0u;
		}
		i++;
		for (uint8_t k = 1u; k < code; k++) {
			if ((i >= len) || (o >= cap) || (in[i] == 0u)) {
				return 0u;
			}
			out[o] = in[i];
			o++;
			i++;
		}
		if ((code != 0xFFu) && (i < len)) {
			if (o >= cap) {
				return 0u;
			}
			out[o] = 0u;
			o++;
		}
	}
	return o;
}

/* Build one wire frame: 0x00, COBS(header | payload | crc16), 0x00.
 * Returns bytes written to out, 0 if payload_len > VL_MAX_PAYLOAD or cap is too small. */
static inline size_t vl_frame_encode(uint8_t msg_id, uint8_t seq, const uint8_t *payload, size_t payload_len,
				     uint8_t *out, size_t cap)
{
	uint8_t raw[VL_MAX_FRAME];
	if ((payload_len > VL_MAX_PAYLOAD) || (cap < 3u)) {
		return 0u;
	}
	raw[0] = (uint8_t)VL_SCHEMA_MAJOR;
	raw[1] = msg_id;
	raw[2] = seq;
	raw[3] = (uint8_t)payload_len;
	if (payload_len > 0u) {
		(void)memcpy(&raw[VL_HEADER_LEN], payload, payload_len);
	}
	const size_t body = VL_HEADER_LEN + payload_len;
	vl_put_u16(&raw[body], vl_crc16(raw, body));
	out[0] = 0u;
	const size_t n = vl_cobs_encode(raw, body + VL_CRC_LEN, &out[1], cap - 2u);
	if (n == 0u) {
		return 0u;
	}
	out[n + 1u] = 0u;
	return n + 2u;
}

